function appVersionFileSafe(){
  return String(APP_VERSION).replace(/\./g,"_");
}
function appVersionLabel(){
  return String(APP_VERSION);
}
function appVersionFullLabel(){
  return "גרסה " + APP_VERSION;
}
function enforceAppVersionUI(){
  try{ window.APP_VERSION = APP_VERSION; }catch(e){}
  try{ document.title = "מעקב עבודה - גרסה " + APP_VERSION; }catch(e){}
  try{
    document.querySelectorAll("[data-app-version],#appVersion,#versionLabel,.app-version-mini span,.app-version-footer span").forEach(function(el){
      el.textContent = APP_VERSION;
    });
  }catch(e){}
  try{
    document.querySelectorAll(".secret,#secretTap").forEach(function(el){
      el.textContent = "גרסה " + APP_VERSION;
    });
  }catch(e){}
  try{
    document.querySelectorAll("body *").forEach(function(el){
      if(!el || !el.childNodes || !el.childNodes.length) return;
      el.childNodes.forEach(function(node){
        if(node.nodeType === 3 && node.nodeValue && node.nodeValue.indexOf("${APP_VERSION}") !== -1){
          node.nodeValue = node.nodeValue.replaceAll("${APP_VERSION}", APP_VERSION);
        }
      });
    });
  }catch(e){}
}

