function llDateV523(value){
  try{
    if(!value) return null;
    if(value instanceof Date) return value;
    if(value && typeof value.toDate === "function") return value.toDate();
    if(value && typeof value.seconds === "number") return new Date(value.seconds*1000);
    if(typeof value === "string"){
      const d=new Date(value);
      return isNaN(d.getTime()) ? null : d;
    }
    if(typeof value === "number") return new Date(value);
  }catch(e){}
  return null;
}
function llLabelV523(value){
  const d=llDateV523(value);
  if(!d) return "";
  try{
    return d.toLocaleString("he-IL",{
      timeZone:"Asia/Jerusalem",
      day:"2-digit",
      month:"2-digit",
      year:"2-digit",
      hour:"2-digit",
      minute:"2-digit"
    });
  }catch(e){ return d.toLocaleString(); }
}
function llCurrentUidV523(){
  return (auth && auth.currentUser ? auth.currentUser.uid : "") || (session && session.authUid) || "";
}
function showLastLoginPanelV523(){ console.log("STATIC TEST MODE"); }
function hideLastLoginPanelV523(){
  const panel=document.getElementById("lastLoginPanelV523");
  if(panel) panel.classList.add("hidden");
}
async function refreshLastLoginPanelV523(){
  try{
    const uid=llCurrentUidV523();
    if(!uid){
      showLastLoginPanelV523(null, "לא נמצא UID מחובר");
      return;
    }

    const ref=db.collection("users").doc(uid);
    let previous=null;

    try{
      const doc=await ref.get();
      if(doc.exists){
        const d=doc.data() || {};
        previous=d.lastLoginAt || d.lastLoginClientAt || null;
      }
      showLastLoginPanelV523(previous, "");
    }catch(readErr){
      showLastLoginPanelV523(null, readErr.code || readErr.message || String(readErr));
      return;
    }

    try{
      await ref.set({
        lastLoginAt:firebase.firestore.FieldValue.serverTimestamp(),
        lastLoginClientAt:new Date().toISOString(),
        updatedAt:firebase.firestore.FieldValue.serverTimestamp()
      },{merge:true});
    }catch(writeErr){
      showLastLoginPanelV523(previous, writeErr.code || writeErr.message || String(writeErr));
    }
  }catch(e){
    showLastLoginPanelV523(null, e.code || e.message || String(e));
  }
}

