const AUTH_DOMAIN="work-monitor.local";
function firebaseAuthReady(){return !!(window.firebase && firebase.auth && auth)}
function safeAuthUsernamePart(username){return normalize(username).replace(/[^a-z0-9_\-א-ת]/gi,"_") || "worker"}
function authEmailFromUsername(username){return `${safeAuthUsernamePart(username)}@${AUTH_DOMAIN}`}
function currentAuthUid(){try{return firebaseAuthReady() && auth.currentUser ? auth.currentUser.uid : ""}catch(e){return ""}}
async function ensureUserRoleDoc(uid,role,extra={}){
  if(!uid)return;
  try{
    await db.collection("users").doc(uid).set({uid,role,...extra,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
  }catch(e){console.warn("ensureUserRoleDoc failed",e)}
}
async function tryWorkerAuthLogin(username,pass,worker){
  if(!firebaseAuthReady())return {ok:false,reason:"auth_not_loaded"};
  const email=worker.authEmail || authEmailFromUsername(username);
  try{
    const cred=await auth.signInWithEmailAndPassword(email,pass);
    const uid=cred && cred.user ? cred.user.uid : "";
    if(uid){
      await db.collection("workers").doc(worker.id).set({
        authUid:uid,
        authEmail:email,
        authReady:true,
        authLinkedAt:firebase.firestore.FieldValue.serverTimestamp(),
        updatedAt:firebase.firestore.FieldValue.serverTimestamp()
      },{merge:true});
      await ensureUserRoleDoc(uid,"worker",{workerId:worker.id,username:worker.username||username,name:worker.name||""});
      worker.authUid=uid;worker.authEmail=email;worker.authReady=true;
      return {ok:true,uid,email};
    }
  }catch(e){
    // זה שלב הכנה בלבד: אם המשתמש עדיין לא קיים ב-Firebase Auth, ממשיכים עם הכניסה הישנה ולא שוברים את המערכת.
    console.warn("Firebase Auth login skipped/fallback:",e.code||e.message);
    return {ok:false,reason:e.code||e.message,email};
  }
  return {ok:false,email};
}
async function createOrLoginWorkerAuth(username,pass,name){
  if(!firebaseAuthReady())return {ok:false,reason:"auth_not_loaded",email:authEmailFromUsername(username)};
  const email=authEmailFromUsername(username);
  try{
    const cred=await auth.createUserWithEmailAndPassword(email,pass);
    const uid=cred && cred.user ? cred.user.uid : "";
    if(uid){
      try{await cred.user.updateProfile({displayName:name||username})}catch(e){}
      await ensureUserRoleDoc(uid,"worker",{username,name,authEmail:email});
      return {ok:true,uid,email,created:true};
    }
  }catch(e){
    if(e.code==="auth/email-already-in-use"){
      try{
        const cred=await auth.signInWithEmailAndPassword(email,pass);
        const uid=cred && cred.user ? cred.user.uid : "";
        if(uid){
          await ensureUserRoleDoc(uid,"worker",{username,name,authEmail:email});
          return {ok:true,uid,email,created:false};
        }
      }catch(loginErr){
        return {ok:false,reason:loginErr.code||loginErr.message,email};
      }
    }
    return {ok:false,reason:e.code||e.message,email};
  }
  return {ok:false,email};
}
