async function workerLogin(){
  const username = val("workerUsername"), pass = val("workerPassword");
  if(!username || !pass) return text("workerLoginMsg","חובה למלא שם משתמש וסיסמה.");

  const usernameKey = normalize(username);
  const workerDocId = workerIdFromUsername(usernameKey);

  try{
    let doc = await db.collection("workers").doc(workerDocId).get();

    if(!doc.exists){
      let q = await db.collection("workers").where("usernameKey","==",usernameKey).where("active","==",true).limit(1).get();
      if(q.empty){
        const all = await db.collection("workers").get();
        const found = all.docs.find(d=>{
          const w = d.data();
          return w.active !== false && (
            normalize(w.usernameKey || "") === usernameKey ||
            normalize(w.username || "") === usernameKey
          );
        });
        if(found) doc = found;
      }else{
        doc = q.docs[0];
      }
      if(!doc.exists) return text("workerLoginMsg","שם משתמש לא קיים או לא פעיל.");
    }

    const worker = {id:doc.id, ...doc.data()};
    if(worker.active === false) return text("workerLoginMsg","העובד לא פעיל.");

    if(worker.passwordHash !== await sha256(pass)){
      return text("workerLoginMsg","סיסמה שגויה.");
    }

    if(isSubscriptionExpired(worker)){
      localStorage.removeItem("workSession");
      session=null;
      showExpiredView(worker);
      return;
    }

    const authResult = await tryWorkerAuthLogin(username, pass, worker);
    const remember = $("rememberMe") && $("rememberMe").checked;
    session = {
      role:"worker",
      workerId:worker.id,
      name:worker.name,
      authUid: authResult.ok ? authResult.uid : (worker.authUid || ""),
      authEmail: authResult.email || worker.authEmail || authEmailFromUsername(username),
      remember,
      loginAt:Date.now(),
      expiresAt: remember ? null : Date.now() + (2*60*60*1000)
    };
    localStorage.setItem("workSession", JSON.stringify(session));
    clearLoginFields();
    await showWorker(worker);
  }catch(e){
    text("workerLoginMsg","שגיאה בכניסה: "+e.message);
  }
}

