async function checkRecentCustomer(inputId, resultId){
  const num=val(inputId);
  const box=$(resultId);
  if(!box)return;
  box.innerHTML="";
  if(!num)return;
  if(!/^\d+$/.test(num)){
    box.innerHTML="<div class='danger'>מספר לקוח חייב להיות ספרות בלבד</div>";
    return;
  }
  if(!viewedWorker || !viewedWorker.id){
    box.innerHTML="<div class='danger'>לא זוהה עובד פעיל לבדיקה.</div>";
    return;
  }
  box.innerHTML="<div class='muted'>בודק עבודות שבוצעו וסידורים מתוזמנים אצל העובד הנוכחי...</div>";
  try{
    const now=new Date();
    const from=new Date(now.getTime()-30*24*60*60*1000);
    const fromStr=formatDate(from);
    const today=todayStr ? todayStr() : formatDate(new Date());

    // חשוב: הבדיקה מוגבלת לעובד הנוכחי בלבד.
    const snap=await db.collection("workEntries")
      .where("workerId","==",viewedWorker.id)
      .where("customerNumber","==",num)
      .get();

    const all=snap.docs
      .map(d=>({id:d.id,...d.data()}))
      .filter(e=>e.workerId===viewedWorker.id)
      .sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));

    // v5.69: מפרידים רשומות not_done כדי שלא יוצגו כעבודה רגילה עם ₪0 בבדיקת לקוח חוזר.
    const notDoneMatches=all
      .filter(e=>String(e.entryStatus||e.status||"")==="not_done")
      .sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));

    const doneMatches=all
      .filter(e=>String(e.entryStatus||e.status||"done")!=="not_done" && (!window.isPlannedV49 || !window.isPlannedV49(e)) && (e.entryStatus||"done")!=="planned" && e.date>=fromStr)
      .sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));

    const plannedMatches=all
      .filter(e=>String(e.entryStatus||e.status||"")!=="not_done" && ((window.isPlannedV49 && window.isPlannedV49(e)) || e.entryStatus==="planned") && String(e.date||"")>=today)
      .sort((a,b)=>String(a.date||"").localeCompare(String(b.date||"")));

    // v5.43: מילוי כתובת אוטומטי ללקוח חוזר.
    // אם נמצאה עבודה אחרונה לאותו לקוח ושדה הכתובת עדיין ריק, הכתובת מתמלאת אוטומטית.
    const addressTargetId = inputId === "sCustomer" ? "sAddress" : (inputId === "iCustomer" ? "iAddress" : "");
    const addressTarget = addressTargetId ? $(addressTargetId) : null;
    const addressSource = doneMatches.find(e=>String(e.address||"").trim()) || plannedMatches.find(e=>String(e.address||"").trim()) || all.find(e=>String(e.address||"").trim());
    if(addressTarget && !String(addressTarget.value||"").trim() && addressSource && addressSource.address){
      addressTarget.value = addressSource.address;
    }

    if(!doneMatches.length && !plannedMatches.length && !notDoneMatches.length){
      box.innerHTML="<div class='recent-ok'>לא נמצאה עבודה שבוצעה ב־30 הימים האחרונים, אין סידור מתוזמן ואין פק״ע שלא בוצעה ללקוח הזה ✅</div>";
      return;
    }

    const parts=[];
    if(doneMatches.length){
      const last=doneMatches[0];
      parts.push(`✅ היית אצל לקוח זה ב־30 הימים האחרונים.<br>פעם אחרונה: ${heDate(last.date)} · ${esc(last.description||"עבודה")} · ${money(last.amount||0)}<br>כתובת: ${esc(last.address||"")}`);
    }
    if(plannedMatches.length){
      const next=plannedMatches[0];
      parts.push(`📋 קיימת קריאה/התקנה מתוזמנת ללקוח זה.<br>מועד קרוב: ${heDate(next.date)} · ${esc(next.description||"סידור מתוזמן")} · צפי ${money(next.amount||0)}<br>כתובת: ${esc(next.address||"")}`);
    }
    if(notDoneMatches.length){
      const nd=notDoneMatches[0];
      const ndReason=nd.notDoneReason ? ` · סיבה: ${esc(nd.notDoneReason)}` : "";
      const ndNote=nd.notDoneNote ? `<br>פירוט: ${esc(nd.notDoneNote)}` : "";
      parts.push(`🚫 קיימת פק״ע מתוזמנת שלא בוצעה ללקוח זה.<br>תאריך: ${heDate(nd.date)} · ${esc(nd.description||"פק״ע מתוזמנת")}${ndReason}<br>כתובת: ${esc(nd.address||"")}${ndNote}`);
    }

    const cls=(doneMatches.length || notDoneMatches.length) ? "recent-box" : "recent-ok";
    box.innerHTML=`<div class="${cls}">${parts.join("<br><br>")}</div>`;
  }catch(e){
    const msg=e && (e.code==="permission-denied" || String(e.message||"").includes("permissions"))
      ? "אין הרשאה לבדוק היסטוריית לקוח. השאילתה כבר מוגבלת לעובד הנוכחי, לכן אם זה חוזר צריך לעדכן Rules שיאפשרו לעובד לקרוא workEntries שלו לפי workerId."
      : "שגיאה בבדיקת לקוח: "+(e.message||e);
    box.innerHTML=`<div class='danger'>${esc(msg)}</div>`;
  }
}
async function fillAddressFromLocation(targetInputId){
  const input=$(targetInputId);
  if(!input)return;
  if(!navigator.geolocation){
    alert("המכשיר לא תומך במיקום.");
    return;
  }
  input.value="מאתר מיקום...";
  navigator.geolocation.getCurrentPosition(async pos=>{
    const lat=pos.coords.latitude;
    const lon=pos.coords.longitude;
    try{
      const url=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lon)}&accept-language=he`;
      const res=await fetch(url,{headers:{"Accept":"application/json"}});
      const data=await res.json();
      input.value=data.display_name || `${lat}, ${lon}`;
    }catch(e){
      input.value=`${lat}, ${lon}`;
      alert("לא הצלחתי להמיר לכתובת, שמתי קואורדינטות במקום.");
    }
  },err=>{
    input.value="";
    alert("לא התקבל אישור מיקום או שהמיקום נכשל: " + err.message);
  },{enableHighAccuracy:true,timeout:12000,maximumAge:60000});
}


function currentCalendarMonthKeyV556(){
  const d = calendarDate instanceof Date ? calendarDate : new Date();
  return d.getFullYear() + "-" + pad(d.getMonth()+1);
}
function getWorkerGoalForMonthV556(monthKey){
  const w = viewedWorker || {};
  const key = monthKey || currentCalendarMonthKeyV556();
  const map = (w && typeof w.monthlyGoalsByMonth === "object" && w.monthlyGoalsByMonth) ? w.monthlyGoalsByMonth : {};
  const keys = Object.keys(map);

  // v5.57 CORE FIX:
  // ברגע שיש לעובד יעדים חודשיים, כל חודש קורא רק את היעד שלו.
  // אם לחודש הנוכחי בלוח אין יעד שמור — מחזירים 0 ולא את היעד האחרון שנשמר,
  // כדי שלא יקרה מצב שמאי/יוני מציגים את אותו יעד אחרון.
  if(keys.length){
    if(Object.prototype.hasOwnProperty.call(map,key)){
      const specific = Number(map[key]||0);
      return Number.isNaN(specific) ? 0 : specific;
    }
    return 0;
  }

  // תאימות לעובדים ישנים שעוד לא נשמר להם monthlyGoalsByMonth בכלל.
  return Number(w.monthlyGoal||0);
}
function syncGoalSettingsMonthV556(){
  if(!viewedWorker) return;
  const monthEl = $("selfGoalMonth");
  const goalEl = $("selfMonthlyGoal");
  const key = currentCalendarMonthKeyV556();
  if(monthEl && !monthEl.dataset.userEditingGoalMonthV557){
    monthEl.value = key;
  }
  const activeKey = monthEl && monthEl.value ? monthEl.value : key;
  if(goalEl && !goalEl.dataset.userEditingGoalV557){
    const g=getWorkerGoalForMonthV556(activeKey);
    goalEl.value = g ? g : "";
  }
}
function bindGoalMonthInputV556(){
  const monthEl = $("selfGoalMonth");
  const goalEl = $("selfMonthlyGoal");
  if(goalEl && !goalEl.dataset.v557Bound){
    goalEl.dataset.v557Bound="1";
    goalEl.addEventListener("focus",function(){goalEl.dataset.userEditingGoalV557="1";});
    goalEl.addEventListener("blur",function(){setTimeout(function(){delete goalEl.dataset.userEditingGoalV557;},250);});
  }
  if(!monthEl || monthEl.dataset.v556Bound) return;
  monthEl.dataset.v556Bound = "1";
  monthEl.addEventListener("focus",function(){monthEl.dataset.userEditingGoalMonthV557="1";});
  monthEl.addEventListener("blur",function(){setTimeout(function(){delete monthEl.dataset.userEditingGoalMonthV557;},250);});
  monthEl.addEventListener("change", function(){
    const goalEl = $("selfMonthlyGoal");
    if(goalEl) goalEl.value = getWorkerGoalForMonthV556(monthEl.value) || "";
  });
}
function renderSmartDashboard(){
  const box=$("smartDashboard");
  if(!box)return;
  const entries=[...monthEntries];
  const total=entries.reduce((s,e)=>s+Number(e.amount||0),0);
  const workDays=[...new Set(entries.map(e=>e.date))].length;
  const avg=workDays?total/workDays:0;
  const services=entries.filter(e=>e.workType==="service");
  const installs=entries.filter(e=>e.workType==="install");
  const returnCalls=services.filter(e=>e.isReturnCall);
  const paidServices=services.filter(e=>!e.isReturnCall);

  const byDay={};
  entries.forEach(e=>groupAdd(byDay,e.date||"ללא תאריך",e.amount));
  const dayKeys=Object.keys(byDay);
  const bestDay=dayKeys.length?dayKeys.reduce((a,b)=>byDay[a]>byDay[b]?a:b):null;
  const weakDay=dayKeys.length?dayKeys.reduce((a,b)=>byDay[a]<byDay[b]?a:b):null;

  const goal=getWorkerGoalForMonthV556();
  const left=Math.max(goal-total,0);
  const remaining=remainingWorkDaysInMonth();
  const needed=remaining?left/remaining:left;
  const progress=goal?Math.min(total/goal*100,100):0;

  const clientMap={};
  entries.forEach(e=>{
    const c=e.customerNumber||"ללא מספר";
    if(!clientMap[c])clientMap[c]={count:0,total:0};
    clientMap[c].count++;
    clientMap[c].total+=Number(e.amount||0);
  });
  const topClient=Object.keys(clientMap).sort((a,b)=>clientMap[b].total-clientMap[a].total)[0];

  const installItems={};
  entries.forEach(e=>(e.items||[]).forEach(i=>{
    if(!installItems[i.name])installItems[i.name]={qty:0,total:0};
    installItems[i.name].qty+=Number(i.quantity||0);
    installItems[i.name].total+=Number(i.total||0);
  }));
  const topItem=Object.keys(installItems).sort((a,b)=>installItems[b].total-installItems[a].total)[0];

  box.innerHTML=`
    <div class="grid4">
      <div class="dash-card"><div class="dash-icon">🔥</div><div class="dash-title">היום הכי חזק</div><div class="dash-value">${bestDay?heDate(bestDay):"אין"}</div><div class="muted">${bestDay?money(byDay[bestDay]):""}</div></div>
      <div class="dash-card"><div class="dash-icon">📉</div><div class="dash-title">היום הכי חלש</div><div class="dash-value">${weakDay?heDate(weakDay):"אין"}</div><div class="muted">${weakDay?money(byDay[weakDay]):""}</div></div>
      <div class="dash-card"><div class="dash-icon">📊</div><div class="dash-title">ממוצע ליום עבודה</div><div class="dash-value">${money(avg)}</div><div class="muted">${workDays} ימי עבודה עם נתונים</div></div>
      <div class="dash-card"><div class="dash-icon">🎯</div><div class="dash-title">קצב ליעד</div><div class="dash-value">${Math.round(progress)}%</div><div class="muted">${left>0?`צריך ${money(needed)} ליום עבודה שנשאר`:"היעד הושג"}</div></div>
    </div>
    <div class="kpi-strip">
      <div class="kpi">סה״כ חודש<b>${money(total)}</b></div>
      <div class="kpi">קריאות שירות<b>${services.length}</b></div>
      <div class="kpi">התקנות<b>${installs.length}</b></div>
      <div class="kpi">קריאות חוזרות<b>${returnCalls.length}</b></div>
    </div>
    <div>
      <span class="badge">✅ קריאות בתשלום: ${paidServices.length}</span>
      <span class="badge">🔁 חוזרות ללא תשלום: ${returnCalls.length}</span>
      <span class="badge">👤 לקוח מוביל: ${topClient?`${esc(topClient)} · ${money(clientMap[topClient].total)}`:"אין"}</span>
      <span class="badge">🧾 פריט התקנה מוביל: ${topItem?`${esc(topItem)} · ${installItems[topItem].qty}`:"אין"}</span>
    </div>
  `;
}
function remainingWorkDaysInMonth(){
  const now=new Date();
  const y=calendarDate.getFullYear(),m=calendarDate.getMonth();

  // v5.20 FIX:
  // בדשבורד החכם "כמה צריך לכל יום עבודה שנשאר" לא אמור לכלול את היום הנוכחי.
  // היום כבר משמש לעדכון הסכום שבוצע בפועל, ולכן ימי העבודה העתידיים מתחילים ממחר.
  const viewedMonthStart=new Date(y,m,1);
  const currentMonthStart=new Date(now.getFullYear(),now.getMonth(),1);
  if(viewedMonthStart < currentMonthStart) return 0;

  const isCurrentMonth=(now.getFullYear()===y && now.getMonth()===m);
  const start=isCurrentMonth ? now.getDate()+1 : 1;
  const last=new Date(y,m+1,0).getDate();

  let count=0;
  for(let d=start;d<=last;d++){
    const dt=new Date(y,m,d);
    if(dt.getDay()!==6)count++;
  }
  return count;
}
function toggleClientHistory(){const p=$("clientHistoryPanel");p.classList.toggle("hidden")}
async function loadClientHistory(){
  const num=val("clientHistoryNumber");
  const box=$("clientHistoryResults");
  if(!num||!/^\d+$/.test(num)){box.innerHTML="<p class='danger'>חובה להכניס מספר לקוח בספרות בלבד.</p>";return}
  if(!viewedWorker || !viewedWorker.id){box.innerHTML="<p class='danger'>לא זוהה עובד פעיל לחיפוש.</p>";return}
  box.innerHTML="<p>טוען היסטוריית לקוח...</p>";
  try{
    // v4.99 FIX:
    // Security Rules מאפשרים לעובד לקרוא רק מסמכים שלו.
    // לכן החיפוש חייב לכלול workerId בשאילתה עצמה, ולא רק customerNumber.
    const snap=await db.collection("workEntries")
      .where("workerId","==",viewedWorker.id)
      .where("customerNumber","==",num)
      .get();
    const entries=snap.docs
      .map(d=>({id:d.id,...d.data()}))
      .filter(e=>e.workerId===viewedWorker.id && String(e.customerNumber||"")===num)
      .sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));
    if(!entries.length){box.innerHTML="<p class='muted'>לא נמצאה היסטוריה ללקוח הזה.</p>";return}
    const total=entries.reduce((s,e)=>s+Number(e.amount||0),0);
    const services=entries.filter(e=>e.workType==="service").length;
    const installs=entries.filter(e=>e.workType==="install").length;
    const addresses=[...new Set(entries.map(e=>e.address).filter(Boolean))];

    box.innerHTML=`
      <div class="client-card">
        <div class="client-head"><h3>לקוח ${esc(num)}</h3><div class="money">${money(total)}</div></div>
        <div class="kpi-strip">
          <div class="kpi">סה״כ עבודות<b>${entries.length}</b></div>
          <div class="kpi">קריאות שירות<b>${services}</b></div>
          <div class="kpi">התקנות<b>${installs}</b></div>
          <div class="kpi">כתובות<b>${addresses.length}</b></div>
        </div>
        <p class="muted">כתובות: ${addresses.map(esc).join(" | ")}</p>
      </div>
    `;
    entries.forEach(e=>{
      const details=e.workType==="install"&&e.items?e.items.map(i=>`${i.name} × ${i.quantity} = ${money(i.total)}`).join("<br>"):(e.isReturnCall?"קריאה חוזרת ללא תשלום":"קריאת שירות");
      const div=document.createElement("div");
      div.className="item";
      div.innerHTML=`<div><div class="item-title">${esc(e.date||"")} · ${esc(e.description||"")}</div><div class="item-sub">כתובת: ${esc(e.address||"")}\\n${nl2br(details)}\\n${nl2br(e.notes||"")}</div></div><div class="money">${money(e.amount||0)}</div>`;
      box.appendChild(div);
    });
  }catch(e){
    box.innerHTML=`<p class='danger'>שגיאה בטעינת היסטוריית לקוח: ${esc(e.message)}</p>`;
  }
}

function toggleSearchPanel(){const p=$("searchPanel");p.classList.toggle("hidden");if(!p.classList.contains("hidden"))renderFullSummary();cleanVisibleSlashN()}
/* ===== v5.07: חיפוש וסיכומים לפי טווח תאריכים בלי לפגוע בברירת המחדל החודשית ===== */
/* ===== v5.09: סנכרון UI בלבד בין חודש נבחר לבין טווח תאריכים =====
   המטרה: לא לשנות את מנוע החיפוש שעובד, אלא למנוע מצב מבלבל שבו גם חודש וגם טווח מלאים יחד.
   - בחירת חודש מנקה את מתאריך/עד תאריך ואת שדה היום הישן שהוסתר.
   - הזנת מתאריך או עד תאריך מנקה את החודש ואת שדה היום הישן שהוסתר.
*/
function setupSearchDateMutualClearV509(){
  const monthEl=$("searchMonth");
  const fromEl=$("searchDateFromV507");
  const toEl=$("searchDateToV507");
  const hiddenDayEl=$("searchDate");
  if(monthEl && !monthEl.dataset.v509Bound){
    monthEl.dataset.v509Bound="1";
    monthEl.addEventListener("input",()=>{
      if(monthEl.value){
        if(fromEl) fromEl.value="";
        if(toEl) toEl.value="";
        if(hiddenDayEl) hiddenDayEl.value="";
        window.searchBaseEntriesV507=null;
      }
    });
  }
  [fromEl,toEl].forEach(el=>{
    if(el && !el.dataset.v509Bound){
      el.dataset.v509Bound="1";
      el.addEventListener("input",()=>{
        if(el.value){
          if(monthEl) monthEl.value="";
          if(hiddenDayEl) hiddenDayEl.value="";
          window.searchBaseEntriesV507=null;
        }
      });
    }
  });
}
window.addEventListener("DOMContentLoaded", setupSearchDateMutualClearV509);
window.addEventListener("load", setupSearchDateMutualClearV509);

function getSearchDateScopeV507(){
  const rangeFrom=val("searchDateFromV507");
  const rangeTo=val("searchDateToV507");
  const singleDate=val("searchDate");
  const month=val("searchMonth");

  // טווח חדש מקבל עדיפות על "יום מסוים"/"חודש מסוים" רק אם הוזן בו לפחות תאריך אחד.
  if(rangeFrom || rangeTo){
    const from=rangeFrom || rangeTo;
    const to=rangeTo || rangeFrom;
    if(from && to && to < from){
      return {error:"תאריך הסיום לא יכול להיות לפני תאריך ההתחלה."};
    }
    return {mode:(rangeFrom && rangeTo && rangeFrom!==rangeTo)?"range":"day", from, to, label:(from===to?`יום ${heDate(from)}`:`${heDate(from)} עד ${heDate(to)}`)};
  }

  if(singleDate){
    return {mode:"day", from:singleDate, to:singleDate, label:`יום ${heDate(singleDate)}`};
  }

  if(month){
    const parts=month.split("-");
    const y=Number(parts[0]), m=Number(parts[1]);
    if(y && m){
      const last=new Date(y,m,0).getDate();
      return {mode:"month", from:`${y}-${pad(m)}-01`, to:`${y}-${pad(m)}-${pad(last)}`, label:`חודש ${month}`};
    }
  }

  return {mode:"currentMonth", label:"החודש בתצוגה"};
}

function hasActiveSearchFiltersV562(){
  // v5.62: אם אין תאריכים אבל כן יש חיפוש/פילטר, מחפשים בכל ההיסטוריה של העובד.
  // סיכום חודש מלא עדיין נשאר על monthEntries בלבד דרך renderFullSummary().
  try{
    if(val("searchCustomer")) return true;
    if(val("searchAddress")) return true;
    if(val("searchType")) return true;
    var pekaEl=document.getElementById("pekaSearchTypeV528");
    if(pekaEl && pekaEl.value) return true;
    if(window.selectedWorkerPriceSearchItemsV38 && window.selectedWorkerPriceSearchItemsV38.size) return true;
    if(window.searchInstallKindV412 && String(window.searchInstallKindV412||"").trim()) return true;
  }catch(e){}
  return false;
}

async function loadAllWorkerEntriesForSearchV562(){
  const workerId=(viewedWorker&&viewedWorker.id)||"";
  if(!workerId) return [];
  const snap=await db.collection("workEntries").where("workerId","==",workerId).get();
  return snap.docs.map(d=>({id:d.id,...d.data()}));
}

async function getSearchBaseEntriesV507(scope){
  const workerId=(viewedWorker&&viewedWorker.id)||"";
  window.searchAllHistoryV562=false;

  // v5.62: בלי תאריך/חודש + יש חיפוש פעיל => כל ההיסטוריה.
  // בלי חיפוש פעיל => נשאר סיכום החודש שמוצג בלוח, כדי לא לשנות את כפתור "סיכום חודש מלא".
  if(!scope || scope.mode==="currentMonth"){
    if(hasActiveSearchFiltersV562()){
      window.searchAllHistoryV562=true;
      return await loadAllWorkerEntriesForSearchV562();
    }
    return Array.isArray(monthEntries) ? monthEntries.slice() : [];
  }

  if(!workerId) return [];
  const snap=await db.collection("workEntries").where("workerId","==",workerId).get();
  return snap.docs
    .map(d=>({id:d.id,...d.data()}))
    .filter(e=>String(e.date||"") >= scope.from && String(e.date||"") <= scope.to);
}


// v5.97: נרמול כתובת לצורך תוצאות קרובות בלבד. החיפוש המדויק ממשיך להשתמש בערך המקורי.
function normalizeAddressSearchV597(value){
  return String(value||"")
    .toLowerCase()
    .replace(/[\u05f3\u05f4'"`]/g," ")
    .replace(/[.,;:()\[\]{}\\/|_-]+/g," ")
    .replace(/\s+/g," ")
    .trim();
}
function normalizeAddressPhraseV597(value){
  return normalizeAddressSearchV597(value)
    .replace(/\b(?:רחוב|רח)\b/g," ")
    .replace(/\s+/g," ")
    .trim();
}
function parseAddressPartsV597(value){
  const raw=normalizeAddressPhraseV597(value);
  if(!raw) return {street:"",city:"",withoutNumber:""};
  const tokens=raw.split(" ").filter(Boolean);
  const numberIndex=tokens.findIndex(token=>/^\d+[א-תa-z]?$/.test(token));
  let streetTokens=[], cityTokens=[];
  if(numberIndex>=0){
    streetTokens=tokens.slice(0,numberIndex);
    cityTokens=tokens.slice(numberIndex+1);
  }else{
    // ללא מספר בית אין דרך בטוחה להפריד רחוב ועיר; הביטוי כולו משמש כהתאמת רחוב.
    streetTokens=tokens.slice();
  }
  return {
    street:streetTokens.join(" ").trim(),
    city:cityTokens.join(" ").trim(),
    withoutNumber:tokens.filter(token=>!/^\d+[א-תa-z]?$/.test(token)).join(" ").trim()
  };
}
function getFilteredEntriesWithoutAddressV597(){
  const customer=val("searchCustomer");
  const type=val("searchType");
  const date=val("searchDate");
  const month=val("searchMonth");
  const scope=getSearchDateScopeV507();
  let arr=Array.isArray(window.searchBaseEntriesV507) ? window.searchBaseEntriesV507.slice() : [...monthEntries];
  if(customer) arr=arr.filter(e=>String(e.customerNumber||"").includes(customer));
  if(type) arr=arr.filter(e=>e.workType===type);
  if(!scope || scope.mode==="currentMonth"){
    if(date) arr=arr.filter(e=>e.date===date);
    if(month) arr=arr.filter(e=>String(e.date||"").startsWith(month));
  }
  return arr;
}
function buildNearbyAddressGroupsV597(exactEntries){
  const query=val("searchAddress");
  if(!String(query||"").trim()) return null;
  const parts=parseAddressPartsV597(query);
  if(!parts.street && !parts.city) return null;
  const exactIds=new Set((exactEntries||[]).map(e=>String(e.id||"")));
  const all=getFilteredEntriesWithoutAddressV597();
  const street=[], city=[];
  const streetIds=new Set();
  for(const entry of all){
    const id=String(entry.id||"");
    if(id && exactIds.has(id)) continue;
    const address=normalizeAddressPhraseV597(entry.address||"");
    const parsed=parseAddressPartsV597(entry.address||"");
    if(parts.street && (parsed.street.includes(parts.street) || address.includes(parts.street))){
      street.push(entry);
      if(id) streetIds.add(id);
      continue;
    }
    if(parts.city && !streetIds.has(id) && (parsed.city.includes(parts.city) || address.includes(parts.city))){
      city.push(entry);
    }
  }
  return {streetTerm:parts.street,cityTerm:parts.city,street,city};
}
function createSearchEntryCardV597(e){
  const details=e.workType==="install" && e.items
    ? e.items.map(i=>`${i.name} × ${i.quantity} = ${money(i.total)}`).join("<br>")
    : (e.isReturnCall?"קריאה חוזרת ללא תשלום":"קריאת שירות");
  const div=document.createElement("div");
  div.className="item smart-entry-link-v584";
  div.innerHTML=`<div><div class="item-title">${esc(e.date||"")} · ${esc(e.description||"")}</div><div class="item-sub">לקוח: ${esc(e.customerNumber||"")}\nכתובת: ${esc(e.address||"")}\n${nl2br(details)}\n${nl2br(e.notes||"")}</div></div><div class="money">${money(e.amount||0)}</div>`;
  const entryId=String(e.id||"");
  const entryDate=String(e.date||"");
  if(entryId && entryDate){
    div.setAttribute("role","button");
    div.setAttribute("tabindex","0");
    div.setAttribute("aria-label",`פתח את הרשומה מתאריך ${entryDate}`);
    const openExactSearchEntry=()=>{
      if(typeof window.openSmartEntryV584==="function") window.openSmartEntryV584(entryId,entryDate);
    };
    div.addEventListener("click",openExactSearchEntry);
    div.addEventListener("keydown",event=>{
      if(event.key==="Enter" || event.key===" "){
        event.preventDefault();
        openExactSearchEntry();
      }
    });
  }
  return div;
}
function appendNearbyAddressResultsV597(results,exactEntries){
  const groups=buildNearbyAddressGroupsV597(exactEntries);
  if(!groups || (!groups.street.length && !groups.city.length)) return;
  const wrapper=document.createElement("div");
  wrapper.className="nearby-address-results-v597";
  const title=document.createElement("h3");
  title.textContent="תוצאות קרובות לכתובת שחיפשת";
  wrapper.appendChild(title);
  const addGroup=(label,term,items)=>{
    if(!term || !items.length) return;
    const shell=document.createElement("div");
    shell.className="search-results-shell-v421 nearby-address-group-v597";
    shell.innerHTML=`<h3>${esc(label)} <strong>„${esc(term)}”</strong> <span class="search-scroll-count-v421">${items.length} תוצאות</span></h3><div class="search-results-scroll-v421"></div>`;
    const scroller=shell.querySelector(".search-results-scroll-v421");
    items.slice().sort((a,b)=>String(b.date||"").localeCompare(String(a.date||""))).forEach(e=>scroller.appendChild(createSearchEntryCardV597(e)));
    wrapper.appendChild(shell);
  };
  addGroup("תוצאות קרובות לפי הרחוב",groups.streetTerm,groups.street);
  addGroup("תוצאות קרובות לפי העיר",groups.cityTerm,groups.city);
  results.appendChild(wrapper);
}

function getFilteredEntries(){
  const customer=val("searchCustomer");
  const address=val("searchAddress").toLowerCase();
  const type=val("searchType");
  const date=val("searchDate");
  const month=val("searchMonth");
  const scope=getSearchDateScopeV507();
  let arr=Array.isArray(window.searchBaseEntriesV507) ? window.searchBaseEntriesV507.slice() : [...monthEntries];

  if(customer) arr=arr.filter(e=>String(e.customerNumber||"").includes(customer));
  if(address) arr=arr.filter(e=>String(e.address||"").toLowerCase().includes(address));
  if(type) arr=arr.filter(e=>e.workType===type);

  // אם הופעל טווח v5.07, אין צורך במסנני יום/חודש הישנים כי הבסיס כבר מסונן לפי הטווח.
  if(!scope || scope.mode==="currentMonth"){
    if(date) arr=arr.filter(e=>e.date===date);
    if(month) arr=arr.filter(e=>String(e.date||"").startsWith(month));
  }

  return arr;
}
async function runSearch(){
  const scope=getSearchDateScopeV507();
  if(scope && scope.error){ alert(scope.error); return; }
  const summaryBox=$("summaryResults");
  const resultsBox=$("searchResults");
  if(summaryBox) summaryBox.innerHTML="<div class='notice'>טוען חיפוש...</div>";
  if(resultsBox) resultsBox.innerHTML="";
  try{
    window.searchBaseEntriesV507=await getSearchBaseEntriesV507(scope);
    const title=window.searchAllHistoryV562
      ? "תוצאות חיפוש - כל ההיסטוריה"
      : (scope && scope.mode!=="currentMonth" ? `תוצאות חיפוש - ${scope.label}` : "תוצאות חיפוש");
    renderSummary(getFilteredEntries(), title);
  }catch(e){
    if(summaryBox) summaryBox.innerHTML=`<p class='danger'>שגיאה בחיפוש: ${esc(e.message)}</p>`;
  }
}
function clearSearch(){
  ["searchCustomer","searchAddress","searchDate","searchDateFromV507","searchDateToV507","searchMonth"].forEach(id=>{ if($(id)) $(id).value=""; });
  $("searchType").value="";
  window.searchBaseEntriesV507=null;
  renderFullSummary();
}
function renderFullSummary(){window.searchBaseEntriesV507=null;renderSummary(monthEntries, "סיכום חודש בתצוגה")}
function getWeekKey(dateStr){
  const d=parseDate(dateStr);
  const first=new Date(d.getFullYear(),0,1);
  const days=Math.floor((d-first)/86400000);
  const week=Math.ceil((days+first.getDay()+1)/7);
  return `${d.getFullYear()} שבוע ${week}`;
}
function groupAdd(obj,key,amount){if(!obj[key])obj[key]=0;obj[key]+=Number(amount||0)}
function renderSummary(entries,title){
  const box=$("summaryResults");
  const results=$("searchResults");
  if(!box||!results)return;

  const list=[...entries];
  const total=list.reduce((s,e)=>s+Number(e.amount||0),0);
  const services=list.filter(e=>e.workType==="service");
  const installs=list.filter(e=>e.workType==="install");
  const paidServices=services.filter(e=>!e.isReturnCall);
  const returnServices=services.filter(e=>e.isReturnCall);

  const byDay={}, byWeek={}, byType={"קריאות שירות":0,"התקנות":0};
  const byInstallItem={};

  list.forEach(e=>{
    groupAdd(byDay,e.date||"ללא תאריך",e.amount);
    groupAdd(byWeek,getWeekKey(e.date),e.amount);
    if(e.workType==="service") groupAdd(byType,"קריאות שירות",e.amount);
    if(e.workType==="install") groupAdd(byType,"התקנות",e.amount);
    if(e.items) e.items.forEach(i=>{
      if(!byInstallItem[i.name]) byInstallItem[i.name]={qty:0,total:0};
      byInstallItem[i.name].qty+=Number(i.quantity||0);
      byInstallItem[i.name].total+=Number(i.total||0);
    });
  });

  const dayCount=Object.keys(byDay).length;
  const weekCount=Object.keys(byWeek).length;
  const typeCount=Object.keys(byType).filter(k=>Number(byType[k]||0)>0).length;
  const itemCount=Object.keys(byInstallItem).length;

  box.innerHTML=`
    <h3>${esc(title)}</h3>
    <div class="grid4">
      <div class="stat"><div class="label">סה״כ כסף</div><div class="value">${money(total)}</div></div>
      <div class="stat"><div class="label">קריאות שירות</div><div class="value">${services.length}</div></div>
      <div class="stat"><div class="label">התקנות</div><div class="value">${installs.length}</div></div>
      <div class="stat"><div class="label">קריאות חוזרות</div><div class="value">${returnServices.length}</div></div>
    </div>

    <div class="search-summary-grid-v421">
      <div class="card search-scroll-card-v421">
        <h3>לפי ימים <span class="search-scroll-count-v421">${dayCount} ימים</span></h3>
        <div class="search-scroll-box-v421">${renderMiniTable(byDay)}</div>
      </div>
      <div class="card search-scroll-card-v421">
        <h3>לפי שבועות <span class="search-scroll-count-v421">${weekCount} שבועות</span></h3>
        <div class="search-scroll-box-v421">${renderMiniTable(byWeek)}</div>
      </div>
      <div class="card search-scroll-card-v421">
        <h3>לפי סוג עבודה <span class="search-scroll-count-v421">${typeCount} סוגים</span></h3>
        <div class="search-scroll-box-v421">${renderMiniTable(byType)}</div>
      </div>
      <div class="card search-scroll-card-v421">
        <h3>פירוט פריטי התקנה <span class="search-scroll-count-v421">${itemCount} פריטים</span></h3>
        <div class="search-scroll-box-v421">${renderInstallItemsSummary(byInstallItem)}</div>
      </div>
    </div>
    <p class="muted">קריאות שירות בתשלום: ${paidServices.length} · קריאות חוזרות ללא תשלום: ${returnServices.length}</p>
  `;

  results.innerHTML = list.length
    ? `<div class="search-results-shell-v421"><h3>פירוט תוצאות <span class="search-scroll-count-v421">${list.length} תוצאות</span></h3><div id="searchResultsScrollV421" class="search-results-scroll-v421"></div></div>`
    : "<p class='muted'>אין תוצאות.</p>";

  const target=$("searchResultsScrollV421");
  if(target){
    list
      .sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")))
      .forEach(e=>target.appendChild(createSearchEntryCardV597(e)));
  }
  // v5.97: רק בחיפוש כתובת מוסיפים מתחת לתוצאות המדויקות קבוצות קרובות לפי רחוב ועיר.
  appendNearbyAddressResultsV597(results,list);
  if(typeof cleanVisibleSlashN === "function") cleanVisibleSlashN();
}

function renderMiniTable(obj){
  const keys=Object.keys(obj).sort();
  if(!keys.length)return "<p class='muted'>אין נתונים.</p>";
  return keys.map(k=>`<div class="item"><div class="item-title">${esc(k)}</div><div class="money">${money(obj[k])}</div></div>`).join("");
}
function renderInstallItemsSummary(obj){
  const keys=Object.keys(obj).sort();
  if(!keys.length)return "<p class='muted'>אין פריטי התקנה.</p>";
  return keys.map(k=>`<div class="item"><div><div class="item-title">${esc(k)}</div><div class="item-sub">כמות: ${obj[k].qty}</div></div><div class="money">${money(obj[k].total)}</div></div>`).join("");
}

function toggleWorkerSettings(){const p=$("workerSettingsPanel");p.classList.toggle("hidden");try{bindGoalMonthInputV556();if($("selfGoalMonth"))$("selfGoalMonth").value=currentCalendarMonthKeyV556();if(viewedWorker&&$("selfMonthlyGoal"))$("selfMonthlyGoal").value=getWorkerGoalForMonthV556();}catch(e){}}
async function saveWorkerSelfSettings(){
  if(!viewedWorker)return;

  const msg=$("selfSettingsMsg");
  const goal=Number(val("selfMonthlyGoal")||0);
  const pass=val("selfNewPassword");
  const monthKey=(val("selfGoalMonth") || currentCalendarMonthKeyV556());

  if(Number.isNaN(goal)||goal<0){
    if(msg) msg.innerHTML="<p class='danger'>יעד חודשי לא תקין.</p>";
    return;
  }

  const monthlyGoalsByMonth=Object.assign({}, viewedWorker.monthlyGoalsByMonth||{});
  monthlyGoalsByMonth[monthKey]=goal;

  const update={
    monthlyGoal:goal,
    monthlyGoalsByMonth,
    updatedAt:firebase.firestore.FieldValue.serverTimestamp()
  };

  if(pass){
    // v4.90 FIX:
    // שינוי סיסמה של עובד חייב לעדכן את Firebase Auth לפני עדכון passwordHash במסמך העובד.
    // בגרסאות הקודמות עודכן רק passwordHash, אבל הכניסה בפועל מתבצעת דרך Auth ולכן הסיסמה החדשה לא התקבלה אחרי יציאה.
    if(pass.length<6){
      if(msg) msg.innerHTML="<p class='danger'>סיסמה חייבת להיות לפחות 6 תווים.</p>";
      return;
    }

    if(!firebaseAuthReady() || !auth.currentUser){
      if(msg) msg.innerHTML="<p class='danger'>Firebase Auth עדיין לא מוכן. צא והיכנס שוב ואז שנה סיסמה.</p>";
      return;
    }

    if(viewedWorker.authUid && auth.currentUser.uid && viewedWorker.authUid!==auth.currentUser.uid){
      if(msg) msg.innerHTML="<p class='danger'>המשתמש המחובר ב־Auth לא תואם לעובד הנוכחי. צא והיכנס מחדש.</p>";
      return;
    }

    try{
      await auth.currentUser.updatePassword(pass);
    }catch(e){
      const code=e && e.code ? e.code : "";
      const needsRelogin = code==="auth/requires-recent-login" || String(e.message||"").includes("recent");
      const humanMsg = needsRelogin
        ? "מטעמי אבטחה Firebase דורש התחברות מחדש לפני שינוי סיסמה. צא, היכנס עם הסיסמה הנוכחית, ואז שנה שוב."
        : "שגיאה בעדכון סיסמת Firebase Auth: "+(e.message||e);
      if(msg) msg.innerHTML=`<p class='danger'>${esc(humanMsg)}</p>`;
      if(typeof writeAppLogV167==="function"){
        await writeAppLogV167("workerSelfPasswordUpdateFailedV490",{
          workerId:viewedWorker.id||"",
          authUid:auth.currentUser ? auth.currentUser.uid : "",
          errorCode:code,
          errorMessage:e.message||String(e)
        }).catch(()=>{});
      }
      return;
    }

    // v4.90 FIX:
    // רק לאחר שהסיסמה עודכנה בהצלחה ב־Auth, מעדכנים את ההאש במסמך העובד כדי שהנתונים יישארו מסונכרנים.
    update.passwordHash=await sha256(pass);
    update.passwordChangedAt=firebase.firestore.FieldValue.serverTimestamp();
  }

  await db.collection("workers").doc(viewedWorker.id).set(update,{merge:true});
  viewedWorker.monthlyGoal=goal;
  viewedWorker.monthlyGoalsByMonth=monthlyGoalsByMonth;
  if(pass){
    viewedWorker.passwordHash=update.passwordHash;
    viewedWorker.passwordChangedAt=new Date().toISOString();
  }
  if($("selfNewPassword")) $("selfNewPassword").value="";
  if(msg) msg.innerHTML=pass
    ? `<div class='notice'>היעד לחודש ${esc(monthKey)} והסיסמה נשמרו ✅<br>בכניסה הבאה השתמש בסיסמה החדשה.</div>`
    : `<div class='notice'>היעד לחודש ${esc(monthKey)} נשמר ✅</div>`;
  renderStats();
  renderSmartDashboard();
}


function showRegister(){clearLoginFields();hideAll();show("registerView");hide("logoutBtn");text("userLine","הרשמה חדשה");["regName","regUsername","regPassword","regPassword2"].forEach(id=>{if($(id))$(id).value=""});if($("registerMsg"))$("registerMsg").innerHTML=""}
function showExpiredView(worker=null){
  hideAll();show("expiredView");hide("logoutBtn");text("userLine","המנוי הסתיים");
  window.expiredWorker = worker || window.expiredWorker || null;
  if(window.expiredWorker){
    if($("paymentWorkerName"))$("paymentWorkerName").value=window.expiredWorker.name||"";
    if($("paymentWorkerUsername"))$("paymentWorkerUsername").value=window.expiredWorker.username||"";
    if($("paymentWorkerId"))$("paymentWorkerId").value=window.expiredWorker.id||"";
  }
  if($("paymentContactPhone"))$("paymentContactPhone").value="";
  if($("paymentMsg"))$("paymentMsg").innerHTML="";
}
function addDaysToDate(days){const d=new Date();d.setDate(d.getDate()+Number(days||0));return formatDate(d)}
function todayStr(){return formatDate(new Date())}
function isPastDate(dateStr){
  if(!dateStr) return false;
  return String(dateStr) < todayStr();
}
function getSubscriptionStatus(worker){
  if(!worker) return "expired";
  return worker.subscriptionStatus || (worker.selfRegistered ? "trial" : "active");
}
function isSubscriptionExpired(worker){
  if(!worker) return true;
  const status = getSubscriptionStatus(worker);

  // חסימה ידנית תמיד גוברת על הכול
  if(status === "blocked") return true;

  // פג תוקף ידני תמיד שולח למסך רכישה
  if(status === "expired") return true;

  // מנוי פעיל: בודקים רק תאריך מנוי. אם אין תאריך — פתוח ללא הגבלת זמן
  if(status === "active"){
    const until = worker.subscriptionUntil || "";
    if(!until) return false;
    return isPastDate(until);
  }

  // ניסיון: בודקים תאריך ניסיון, ואם אין — תאריך מנוי כגיבוי
  if(status === "trial"){
    const until = worker.trialUntil || worker.subscriptionUntil || "";
    if(!until) return false;
    return isPastDate(until);
  }

  // ברירת מחדל בטוחה לעובדים ישנים בלי סטטוס ברור
  const until = worker.subscriptionUntil || worker.trialUntil || "";
  if(!until) return false;
  return isPastDate(until);
}
function isSessionExpired(){
  if(!session) return true;
  if(session.remember) return false;
  return session.expiresAt && Date.now() > Number(session.expiresAt);
}
async function registerWorker(){
  const name=val("regName"),username=val("regUsername"),pass=val("regPassword"),pass2=val("regPassword2");
  const msg=$("registerMsg");
  msg.innerHTML="";
  if(!name||!username||!pass||!pass2){msg.innerHTML="<p class='danger'>חובה למלא את כל השדות.</p>";return}
  if(pass!==pass2){msg.innerHTML="<p class='danger'>הסיסמאות לא תואמות.</p>";return}
  if(pass.length<4){msg.innerHTML="<p class='danger'>סיסמה קצרה מדי.</p>";return}

  const usernameKey=normalize(username);
  const id=workerIdFromUsername(usernameKey);
  const ref=db.collection("workers").doc(id);
  const existing=await ref.get();
  if(existing.exists){msg.innerHTML="<p class='danger'>שם המשתמש כבר קיים.</p>";return}

  const trialUntil=addDaysToDate(DEFAULT_TRIAL_DAYS);
  const authResult=await createOrLoginWorkerAuth(username,pass,name);
  await ref.set({
    name,
    username,
    usernameKey,
    authEmail:authResult.email || authEmailFromUsername(username),
    authUid:authResult.uid || "",
    authReady:!!authResult.ok,
    authNote:authResult.ok ? "Firebase Auth מוכן" : ("Legacy fallback: " + (authResult.reason || "לא נוצר Auth")),
    passwordHash:await sha256(pass),
    monthlyGoal:0,
    active:true,
    selfRegistered:true,
    subscriptionStatus:"trial",
    trialDays:DEFAULT_TRIAL_DAYS,
    trialUntil,
    subscriptionUntil:trialUntil,
    createdAt:firebase.firestore.FieldValue.serverTimestamp(),
    updatedAt:firebase.firestore.FieldValue.serverTimestamp()
  });

  msg.innerHTML=`<div class='notice'>המשתמש נפתח בהצלחה ✅<br>תקופת ניסיון עד ${heDate(trialUntil)}<br>${authResult.ok?"Firebase Auth חובר ✅":"המשתמש עובד במצב תאימות ישן עד הפעלת Auth/Cloud Function"}</div>`;
}
async function saveTrialSettings(){
  const days=Number(val("trialDaysInput")||0);
  if(Number.isNaN(days)||days<1){$("trialSettingsMsg").innerHTML="<p class='danger'>מספר ימי ניסיון לא תקין.</p>";return}
  DEFAULT_TRIAL_DAYS=days;
  await db.collection("settings").doc("main").set({defaultTrialDays:days,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
  $("trialSettingsMsg").innerHTML="<div class='notice'>ימי ניסיון נשמרו ✅</div>";
}
function openSubscriptionEdit(workerId){
  const w=workers.find(x=>x.id===workerId);
  if(!w)return;
  show("subscriptionEditPanel");
  $("subWorkerId").value=w.id;
  $("subWorkerName").value=`${w.name} (${w.username})`;
  $("subUntilDate").value=w.subscriptionUntil||w.trialUntil||"";
  $("subStatus").value=getSubscriptionStatus(w);
  $("subscriptionMsg").innerHTML="";
  updateSubscriptionStatusHint();
  window.scrollTo({top:$("subscriptionEditPanel").offsetTop-20,behavior:"smooth"});
}
function updateSubscriptionStatusHint(){
  const hint=$("subscriptionStatusHint");
  if(!hint)return;
  const status=val("subStatus"), until=val("subUntilDate");
  if(status==="blocked"){hint.innerHTML="🔒 חסום: העובד לא יוכל להיכנס, בלי קשר לתאריך.";return}
  if(status==="expired"){hint.innerHTML="❌ פג תוקף: העובד יועבר למסך רכישת מנוי, בלי קשר לתאריך.";return}
  if(status==="trial"){hint.innerHTML=until?`🧪 ניסיון פעיל עד ${heDate(until)}. אחרי התאריך העובד יעבור למסך רכישה.`:"🧪 ניסיון בלי תאריך — כרגע לא ייחסם אוטומטית. מומלץ להגדיר תאריך.";return}
  if(status==="active" && !until){hint.innerHTML="✅ מנוי פעיל ללא תאריך — גישה פתוחה ללא הגבלת זמן.";return}
  if(status==="active" && isPastDate(until)){hint.innerHTML="⚠️ מנוי פעיל עם תאריך שעבר — אי אפשר לשמור כך. בחר תאריך עתידי או נקה את התאריך.";return}
  if(status==="active"){hint.innerHTML=`✅ מנוי פעיל עד ${heDate(until)}.`;return}
}
async function saveSubscriptionEdit(){
  const id=val("subWorkerId"),until=val("subUntilDate"),status=val("subStatus");
  if(!id)return;

  if(status==="active" && until && isPastDate(until)){
    $("subscriptionMsg").innerHTML="<p class='danger'>התאריך שבחרת כבר עבר. למנוי פעיל בחר תאריך עתידי או נקה את התאריך כדי לתת גישה ללא הגבלה.</p>";
    updateSubscriptionStatusHint();
    return;
  }

  if(status==="trial" && until && isPastDate(until)){
    $("subscriptionMsg").innerHTML="<p class='danger'>תאריך הניסיון כבר עבר. בחר תאריך עתידי או שנה את הסטטוס לפג תוקף.</p>";
    updateSubscriptionStatusHint();
    return;
  }

  const update={
    subscriptionUntil:until,
    subscriptionStatus:status,
    active:status!=="blocked",
    updatedAt:firebase.firestore.FieldValue.serverTimestamp()
  };

  if(status==="trial") update.trialUntil=until;

  await db.collection("workers").doc(id).set(update,{merge:true});
  $("subscriptionMsg").innerHTML="<div class='notice'>המנוי נשמר ✅</div>";
  updateSubscriptionStatusHint();
  await loadWorkers();
}
async function extendSubscriptionDays(days){
  const current=val("subUntilDate");
  let base=current?parseDate(current):new Date();
  if(base<new Date())base=new Date();
  base.setDate(base.getDate()+days);
  $("subUntilDate").value=formatDate(base);
  await saveSubscriptionEdit();
}

