/* ===== v3.4: גרסה אחת + טעינה שלא נתקעת ===== */
(function(){
  function applySingleVersionV34(){
    try{ window.APP_VERSION = APP_VERSION; }catch(e){}
    try{ document.title = "מעקב עבודה - גרסה " + APP_VERSION; }catch(e){}
    try{
      document.querySelectorAll(".secret,#secretTap,[data-app-version],#appVersion,#versionLabel").forEach(function(el){
        el.textContent = el.classList && el.classList.contains("secret") ? ("גרסה " + APP_VERSION) : APP_VERSION;
      });
    }catch(e){}
  }

  function isStartupStillVisibleV34(){
    var el=document.getElementById("startupView");
    return !!(el && !el.classList.contains("hidden"));
  }

  function showSafeLoginV34(message){
    try{
      localStorage.removeItem("workExpiredWorkerSession");
      if(typeof clearLoginFields === "function") clearLoginFields();
      if(typeof hideAll === "function") hideAll();
      if(typeof show === "function") show("workerLoginView");
      if(typeof hide === "function") hide("logoutBtn");
      if(typeof text === "function") text("userLine","לא מחובר");
      var msg=document.getElementById("workerLoginMsg");
      if(msg && message) msg.textContent=message;
    }catch(e){
      var s=document.getElementById("startupView");
      var l=document.getElementById("workerLoginView");
      if(s) s.classList.add("hidden");
      if(l) l.classList.remove("hidden");
    }
  }

  function timeoutV34(ms,label){
    return new Promise(function(_,reject){
      setTimeout(function(){reject(new Error(label || "timeout"));}, ms);
    });
  }

  async function bootV34(){
    applySingleVersionV34();
    try{ if(typeof showStartupV179 === "function") showStartupV179(); }catch(e){}

    var fallback=setTimeout(function(){
      if(isStartupStillVisibleV34()){
        showSafeLoginV34("הטעינה לקחה יותר מדי זמן. אפשר להתחבר שוב.");
      }
    }, 60000);

    try{
      try{
        await Promise.race([
          (async function(){
            if(typeof ensureDefaultPriceList === "function") await ensureDefaultPriceList();
            if(typeof loadSettings === "function") await loadSettings();
          })(),
          timeoutV34(4500,"startup_settings_timeout")
        ]);
      }catch(e){ console.warn("startup settings skipped", e); }

      try{ if(typeof attachLoginFieldCleaner === "function") attachLoginFieldCleaner(); }catch(e){}

      var saved=null;
      try{ saved=localStorage.getItem("workSession"); }catch(e){}
      if(saved){
        try{
          session=JSON.parse(saved);
          if(session && session.role === "admin"){
            if(typeof clearLoginFields === "function") clearLoginFields();
            try{ if(typeof waitForAuthReadyV169 === "function") await Promise.race([waitForAuthReadyV169(), timeoutV34(3000,"auth_timeout")]); }catch(e){}
            await Promise.race([showAdmin(), timeoutV34(60000,"show_admin_timeout")]);
            clearTimeout(fallback); applySingleVersionV34(); return;
          }
          if(session && session.role === "worker"){
            if(typeof isSessionExpired === "function" && isSessionExpired()){
              localStorage.removeItem("workSession"); session=null;
              showSafeLoginV34(""); clearTimeout(fallback); applySingleVersionV34(); return;
            }
            if(typeof clearLoginFields === "function") clearLoginFields();
            try{ if(typeof waitForAuthReadyV169 === "function") await Promise.race([waitForAuthReadyV169(), timeoutV34(3000,"auth_timeout")]); }catch(e){}
            await Promise.race([showWorkerById(session.workerId), timeoutV34(60000,"show_worker_timeout")]);
            clearTimeout(fallback); applySingleVersionV34(); return;
          }
        }catch(e){
          console.warn("saved session restore failed", e);
          try{ localStorage.removeItem("workSession"); }catch(_e){}
          session=null;
        }
      }

      clearTimeout(fallback);
      showSafeLoginV34("");
      applySingleVersionV34();
    }catch(e){
      console.warn("boot failed", e);
      clearTimeout(fallback);
      try{ localStorage.removeItem("workSession"); }catch(_e){}
      session=null;
      showSafeLoginV34("הייתה תקלה בטעינה. התחבר מחדש.");
      applySingleVersionV34();
    }
  }

  window.onload = bootV34;
  document.addEventListener("DOMContentLoaded", function(){
    applySingleVersionV34();
    setTimeout(function(){ if(isStartupStillVisibleV34()) bootV34(); }, 900);
  });
})();
;
/* ===== v3.5: ניקוי כלי מעבר ישנים + יציאה יציבה ===== */
(function(){
  const DEPRECATED_ADMIN_IDS_V35 = [
    "securityToolsV169",
    "selfRegistrationToolsV176",
    "recoveryInfoPanelV178",
    "rulesWarningV185",
    "adminAuthBootstrapPanelV170"
  ];
  const DEPRECATED_ADMIN_TEXTS_V35 = [
    "תיקון הרשאות 2.2",
    "הרשמה עצמית 2.2",
    "שחזור גישה לעובד 2.2",
    "סנכרן אבטחה",
    "העתק Security Rules",
    "העתק Rules 2.2",
    "העתק סקיוריטי",
    "Security Rules 2.2",
    "צור/תקן Auth למנהל"
  ];

  function removeNodeV35(el){ try{ if(el && el.parentNode) el.parentNode.removeChild(el); }catch(e){} }

  window.cleanupDeprecatedAdminToolsV35 = function(){
    DEPRECATED_ADMIN_IDS_V35.forEach(id=>removeNodeV35(document.getElementById(id)));
    const admin=document.getElementById("adminView");
    if(!admin) return;
    admin.querySelectorAll(".card,.panel,.paywall").forEach(card=>{
      const txt=String(card.textContent||"");
      if(DEPRECATED_ADMIN_TEXTS_V35.some(t=>txt.includes(t))) removeNodeV35(card);
    });
    admin.querySelectorAll("button").forEach(btn=>{
      const txt=String(btn.textContent||"").trim();
      const onclick=String(btn.getAttribute("onclick")||"");
      if(txt.includes("שחזור גישה") || txt.includes("סנכרן אבטחה") || txt.includes("העתק Rules") || txt.includes("העתק Security Rules") || onclick.includes("resetWorkerAccess") || onclick.includes("manualSyncSecurity") || onclick.includes("copySecurityRules")){
        removeNodeV35(btn);
      }
    });
  };

  window.addSecurityToolsV169 = function(){};
  window.addSelfRegistrationToolsV176 = function(){};
  window.addRecoveryInfoPanelV178 = function(){};
  window.addRulesWarningV185 = function(){};
  window.copySecurityRulesV169 = function(){ alert("כלי Security Rules הוסר מהאדמין בגרסה " + APP_VERSION + ". משתמשים חדשים נוצרים ממסך הכניסה עם Firebase UID אוטומטי."); };
  window.manualSyncSecurityV169 = function(){};

  window.logout = async function(){
    window.__isLoggingOutV180 = true;
    try{ localStorage.removeItem("workSession"); }catch(e){}
    try{ localStorage.removeItem("workExpiredWorkerSession"); }catch(e){}
    try{ session=null; viewedWorker=null; selectedDate=null; selectedType=null; monthEntries=[]; }catch(e){}
    try{ if(typeof clearLoginFields === "function") clearLoginFields(); }catch(e){}
    try{ if(typeof hideAll === "function") hideAll(); }catch(e){}
    try{ if(typeof show === "function") show("workerLoginView"); else document.getElementById("workerLoginView")?.classList.remove("hidden"); }catch(e){}
    try{ if(typeof hide === "function") hide("logoutBtn"); else document.getElementById("logoutBtn")?.classList.add("hidden"); }catch(e){}
    try{ if(typeof text === "function") text("userLine","לא מחובר"); }catch(e){}
    try{ if(firebaseAuthReady()) await auth.signOut(); }catch(e){ console.warn("logout signOut skipped", e); }
    window.__isLoggingOutV180 = false;
  };

  const baseLoadWorkersV35 = window.loadWorkers;
  if(typeof baseLoadWorkersV35 === "function"){
    window.loadWorkers = async function(){
      await baseLoadWorkersV35.apply(this, arguments);
      cleanupDeprecatedAdminToolsV35();
    };
  }

  const baseShowAdminV35 = window.showAdmin;
  if(typeof baseShowAdminV35 === "function"){
    window.showAdmin = async function(){
      await baseShowAdminV35.apply(this, arguments);
      cleanupDeprecatedAdminToolsV35();
      setTimeout(cleanupDeprecatedAdminToolsV35, 100);
      setTimeout(cleanupDeprecatedAdminToolsV35, 450);
    };
  }

  window.addEventListener("load",()=>setTimeout(cleanupDeprecatedAdminToolsV35,250));
})();
;
/* ===== v3.7: Robust return from expired subscription screen ===== */
(function(){
  function safeHideV37(id){ try{ var el=document.getElementById(id); if(el) el.classList.add('hidden'); }catch(e){} }
  function safeShowV37(id){ try{ var el=document.getElementById(id); if(el) el.classList.remove('hidden'); }catch(e){} }
  function clearExpiredAndSessionV37(){
    try{ localStorage.removeItem('workSession'); }catch(e){}
    try{ localStorage.removeItem('workExpiredWorkerSession'); }catch(e){}
    try{ session=null; viewedWorker=null; window.expiredWorker=null; selectedDate=null; selectedType=null; monthEntries=[]; }catch(e){}
    try{ if(typeof clearLoginFields === 'function') clearLoginFields(); }catch(e){}
  }
  window.returnFromExpiredToLoginV37 = function(ev){
    try{ if(ev && ev.preventDefault) ev.preventDefault(); }catch(e){}
    clearExpiredAndSessionV37();
    try{ if(typeof hideAll === 'function') hideAll(); }catch(e){
      ['startupView','workerLoginView','registerView','expiredView','adminLoginView','adminView','workerView'].forEach(safeHideV37);
    }
    safeShowV37('workerLoginView');
    safeHideV37('logoutBtn');
    try{ if(typeof text === 'function') text('userLine','לא מחובר'); }catch(e){
      var u=document.getElementById('userLine'); if(u) u.textContent='לא מחובר';
    }
    try{ var msg=document.getElementById('workerLoginMsg'); if(msg) msg.textContent=''; }catch(e){}
    try{ var wu=document.getElementById('workerUsername'); if(wu) setTimeout(function(){ wu.focus(); },40); }catch(e){}
    return false;
  };

  function upgradeExpiredBackButtonV37(){
    var view=document.getElementById('expiredView'); if(!view) return;
    var btn=document.getElementById('expiredBackToLoginBtn');
    if(!btn){
      var buttons=[].slice.call(view.querySelectorAll('button'));
      btn=buttons.find(function(b){ return String(b.textContent||'').includes('חזרה'); });
      if(btn){ btn.id='expiredBackToLoginBtn'; btn.classList.add('expired-back-btn'); }
    }
    if(btn){
      btn.type='button';
      btn.classList.add('expired-back-btn');
      btn.onclick=window.returnFromExpiredToLoginV37;
    }
  }

  var baseShowExpiredV37 = window.showExpiredView;
  if(typeof baseShowExpiredV37 === 'function'){
    window.showExpiredView = function(){
      var res = baseShowExpiredV37.apply(this, arguments);
      setTimeout(upgradeExpiredBackButtonV37, 0);
      setTimeout(upgradeExpiredBackButtonV37, 120);
      return res;
    };
  }
  document.addEventListener('DOMContentLoaded', upgradeExpiredBackButtonV37);
  window.addEventListener('load', function(){ setTimeout(upgradeExpiredBackButtonV37, 100); });
})();
;
/* ===== v3.9: Stable installation item checklist in search, using global let priceList correctly ===== */
(function(){
  window.selectedWorkerPriceSearchItemsV38 = window.selectedWorkerPriceSearchItemsV38 || new Set();

  function byId(id){ return document.getElementById(id); }
  function safeEscV38(s){
    try{ return typeof esc === 'function' ? esc(s) : String(s||'').replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]||c;}); }
    catch(e){ return String(s||''); }
  }
  function currentSearchTypeV38(){
    var el=byId('searchType');
    return el ? String(el.value||'') : '';
  }
  function getSelectedPriceNamesV38(){
    return Array.from(window.selectedWorkerPriceSearchItemsV38 || []);
  }
  window.clearWorkerPriceSearchV22 = function(){
    window.selectedWorkerPriceSearchItemsV38 = new Set();
    document.querySelectorAll('#priceSearchListV22 input[type="checkbox"]').forEach(function(cb){ cb.checked=false; });
    updatePriceSearchNoteV38();
  };
  function updatePriceSearchNoteV38(){
    var note=byId('priceSearchNoteV22');
    if(!note) return;
    var type=currentSearchTypeV38();
    if(type !== 'install'){
      note.textContent='בחר סוג עבודה: התקנות כדי לפתוח את הצ׳קליסט';
      return;
    }
    var count=getSelectedPriceNamesV38().length;
    note.textContent=count ? ('נבחרו '+count+' פריטי התקנה לסינון') : 'בחר פריטי התקנה לסינון, או השאר ריק כדי לראות את כל ההתקנות';
  }
  function getPriceListForSearchV39(){
    // priceList מוגדר בקובץ הראשי עם let, לכן הוא לא נמצא על window.
    // לכן קודם קוראים למשתנה הגלובלי עצמו, ורק אם לא קיים נופלים ל-window.
    try{
      if(typeof priceList !== 'undefined' && Array.isArray(priceList) && priceList.length){
        return priceList;
      }
    }catch(e){}
    try{
      if(Array.isArray(window.priceList) && window.priceList.length){
        return window.priceList;
      }
    }catch(e){}
    return [];
  }

  function renderPriceSearchListV38(){
    var list=byId('priceSearchListV22');
    if(!list) return;
    var items=getPriceListForSearchV39().filter(function(p){ return p && p.active !== false; });
    if(!items.length){
      list.innerHTML='<div class="muted">לא נטענו פריטי מחירון. סגור ופתח את החיפוש שוב, או רענן את המסך.</div>';
      return;
    }
    list.innerHTML='';
    items.forEach(function(p){
      var name=String(p.name||'');
      var id='priceSearchV38_'+String(p.id||name).replace(/[^a-zA-Z0-9_\-א-ת]/g,'_');
      var label=document.createElement('label');
      label.className='price-search-item-v22';
      label.setAttribute('for', id);
      label.innerHTML='<input id="'+id+'" type="checkbox" data-price-name="'+safeEscV38(name)+'"> <span>'+safeEscV38(name)+'</span>';
      var cb=label.querySelector('input');
      cb.checked=(window.selectedWorkerPriceSearchItemsV38 || new Set()).has(name);
      cb.addEventListener('change', function(){
        if(!window.selectedWorkerPriceSearchItemsV38) window.selectedWorkerPriceSearchItemsV38=new Set();
        if(cb.checked) window.selectedWorkerPriceSearchItemsV38.add(name);
        else window.selectedWorkerPriceSearchItemsV38.delete(name);
        updatePriceSearchNoteV38();
      });
      list.appendChild(label);
    });
    updatePriceSearchNoteV38();
  }
  window.renderWorkerPriceSearchV38 = renderPriceSearchListV38;

  window.onWorkerSearchTypeChangeV22 = async function(){
    var box=byId('workerPriceSearchBoxV22');
    var type=currentSearchTypeV38();
    if(!box) return;
    if(type === 'install'){
      box.classList.remove('hidden');
      var list=byId('priceSearchListV22');
      if(list) list.innerHTML='<div class="muted">טוען פריטי מחירון...</div>';
      try{
        if(!getPriceListForSearchV39().length && typeof loadPriceList === 'function'){
          await loadPriceList();
        }
      }catch(e){
        console.warn('loadPriceList for search failed',e);
      }
      renderPriceSearchListV38();
    }else{
      box.classList.add('hidden');
      window.clearWorkerPriceSearchV22();
    }
  };

  var originalGetFilteredEntriesV38 = window.getFilteredEntries;
  window.getFilteredEntries = function(){
    var arr;
    if(typeof originalGetFilteredEntriesV38 === 'function') arr = originalGetFilteredEntriesV38.apply(this, arguments);
    else arr = Array.isArray(window.monthEntries) ? window.monthEntries.slice() : [];
    if(currentSearchTypeV38() !== 'install') return arr;
    var selected=getSelectedPriceNamesV38();
    if(!selected.length) return arr;
    return arr.filter(function(e){
      if(!e || e.workType !== 'install') return false;
      var items=e.items || [];
      return selected.every(function(name){
        return items.some(function(i){ return String(i.name||'') === String(name); });
      });
    });
  };

  var originalClearSearchV38 = window.clearSearch;
  window.clearSearch = function(){
    if(typeof originalClearSearchV38 === 'function') originalClearSearchV38.apply(this, arguments);
    window.clearWorkerPriceSearchV22();
    var box=byId('workerPriceSearchBoxV22');
    if(box) box.classList.add('hidden');
  };

  var originalToggleSearchPanelV38 = window.toggleSearchPanel;
  window.toggleSearchPanel = async function(){
    if(typeof originalToggleSearchPanelV38 === 'function') originalToggleSearchPanelV38.apply(this, arguments);
    setTimeout(function(){ window.onWorkerSearchTypeChangeV22 && window.onWorkerSearchTypeChangeV22(); },50);
  };

  document.addEventListener('DOMContentLoaded', function(){
    var st=byId('searchType');
    if(st) st.addEventListener('change', function(){ window.onWorkerSearchTypeChangeV22(); });
    setTimeout(function(){ window.onWorkerSearchTypeChangeV22 && window.onWorkerSearchTypeChangeV22(); },150);
  });
  window.addEventListener('load', function(){ setTimeout(function(){ window.onWorkerSearchTypeChangeV22 && window.onWorkerSearchTypeChangeV22(); },250); });
})();
