/* ===== v4.9: סידור עבודה עתידי ===== */
(function(){
  function entryStatusV49(e){ return (e && e.entryStatus) ? e.entryStatus : 'done'; }
  function isPlannedV49(e){ return entryStatusV49(e)==='planned'; }
  function isDoneV49(e){ var st=String((e && (e.entryStatus || e.status)) || 'done'); return !isPlannedV49(e) && st!=='not_done'; }
  function doneEntriesV49(list){ return (Array.isArray(list)?list:[]).filter(isDoneV49); }
  function plannedEntriesV49(list){ return (Array.isArray(list)?list:[]).filter(isPlannedV49); }
  function sumV49(list){ return (Array.isArray(list)?list:[]).reduce(function(s,e){return s+Number(e.amount||0)},0); }
  function workTypeNameV49(e){ return e && e.workType==='install' ? 'התקנה' : 'קריאת שירות'; }
  window.entryStatusV49=entryStatusV49;
  window.isPlannedV49=isPlannedV49;
  window.isDoneV49=isDoneV49;

  function ensurePlannedButtonsV49(){
    try{
      var serviceBtn=document.querySelector('#serviceForm button.btn-green[onclick*="addService"]');
      if(serviceBtn && !document.getElementById('saveServicePlannedBtnV49')){
        serviceBtn.textContent='✅ שמור כבוצע';
        var b=document.createElement('button');
        b.id='saveServicePlannedBtnV49';
        b.type='button';
        b.className='btn-yellow v49-extra-save-btn';
        b.textContent='📋 שמור כסידור עתידי';
        b.onclick=function(){ addServicePlannedV49(); };
        serviceBtn.insertAdjacentElement('afterend', b);
      }
      var installBtn=document.querySelector('#installForm button.btn-green[onclick*="addInstall"]');
      if(installBtn && !document.getElementById('saveInstallPlannedBtnV49')){
        installBtn.textContent='✅ שמור כבוצע';
        var b2=document.createElement('button');
        b2.id='saveInstallPlannedBtnV49';
        b2.type='button';
        b2.className='btn-yellow v49-extra-save-btn';
        b2.textContent='📋 שמור כסידור עתידי';
        b2.onclick=function(){ addInstallPlannedV49(); };
        installBtn.insertAdjacentElement('afterend', b2);
      }
    }catch(e){ console.warn('ensurePlannedButtonsV49 failed',e); }
  }
  window.ensurePlannedButtonsV49=ensurePlannedButtonsV49;


  /*
  ===============================================================================
  CHANGE 5.25 - ACTIVE SAVE HELPERS RESTORED
  -------------------------------------------------------------------------------
  פונקציות השמירה הפעילות V49 קראו לעזרי V516 שלא היו קיימים בקובץ,
  ולכן לחיצה על שמור קריאת שירות / התקנה / מתוזמן נראתה כאילו לא עושה כלום.
  כאן מחזירים את העזרים בתוך אותו scope, בלי לשנות דשבורד או לוגיקה אחרת.
  ===============================================================================
  */
  let wmEntrySaveBusyV525=false;

  function wmBeginEntrySaveV516(){
    if(wmEntrySaveBusyV525) return false;
    wmEntrySaveBusyV525=true;
    try{
      document.querySelectorAll('#serviceForm button,#installForm button').forEach(function(btn){
        if(btn && (btn.textContent||'').includes('שמור')){
          btn.disabled=true;
        }
      });
    }catch(e){}
    return true;
  }

  function wmReleaseEntrySaveV525(){
    setTimeout(function(){
      wmEntrySaveBusyV525=false;
      try{
        document.querySelectorAll('#serviceForm button,#installForm button').forEach(function(btn){
          if(btn) btn.disabled=false;
        });
      }catch(e){}
    },700);
  }

  function wmOfflineSaveNoticeV516(label, amount, status, plannedNote){
    var online=true;
    try{ online=navigator.onLine!==false; }catch(e){}
    var isPlanned=status==='planned';
    var title=(label||'העבודה') + (isPlanned ? ' נשמרה כסידור עתידי ✅' : (online ? ' נשמרה ✅' : ' נשמרה מקומית ✅'));
    var amountText='';
    if(amount!==null && amount!==undefined){
      try{ amountText='סכום: '+(typeof money==='function'?money(amount):('₪'+Number(amount||0))); }catch(e){}
    }
    var syncLine=online
      ? 'אפשר להמשיך להזין עבודה חדשה.'
      : 'אין חיבור כרגע — הנתונים יסתנכרנו אוטומטית כשהאפליקציה תחזור לאונליין.';
    var note=isPlanned && plannedNote ? plannedNote : '';
    return '<div class="save-feedback-v41">'+title+
      (amountText?'<br><span>'+amountText+'</span>':'')+
      '<br><span>'+syncLine+'</span>'+
      (note?'<br><span>'+note+'</span>':'')+
      '</div>';
  }

  function wmResetEntryFormsV525(){
    try{
      if($('sCustomer')) $('sCustomer').value='';
      if($('sAddress')) $('sAddress').value='';
      if($('sNotes')) $('sNotes').value='';
      if($('sCustomerHistory')) $('sCustomerHistory').innerHTML='';
      if($('sReturnCall')) $('sReturnCall').checked=false;
      if(typeof updateServicePreview==='function') updateServicePreview();

      if($('iCustomer')) $('iCustomer').value='';
      if($('iAddress')) $('iAddress').value='';
      if($('iNotes')) $('iNotes').value='';
      if($('iCustomerHistory')) $('iCustomerHistory').innerHTML='';
      if($('installTemplateSelect')) $('installTemplateSelect').value='';
      try{ if(typeof resetPekaTypeV527==='function') resetPekaTypeV527(); }catch(_e){}
      if(Array.isArray(priceList)){
        priceList.forEach(function(p){
          var el=$('qty_'+p.id);
          if(!el) return;
          if((p.inputMode||'qty')==='check') el.checked=false;
          else el.value='';
        });
      }
      if(typeof updateInstallPreview==='function') updateInstallPreview();
    }catch(e){ console.warn('wmResetEntryFormsV525 failed', e); }
  }

  function wmAfterLocalEntrySaveV516(successMsg){
    try{
      var msg=$('entryMsg');
      if(msg) msg.innerHTML=successMsg || '<div class="notice">העבודה נקלטה ✅</div>';
      wmResetEntryFormsV525();
      if(typeof renderDay==='function') renderDay();
      if(typeof renderStats==='function') renderStats();
      if(typeof renderSmartDashboard==='function') renderSmartDashboard();
    }catch(e){ console.warn('wmAfterLocalEntrySaveV516 failed', e); }
    wmReleaseEntrySaveV525();
  }

  function wmHandleEntrySaveErrorV516(err){
    try{
      var msg=$('entryMsg');
      if(msg) msg.innerHTML='<p class="danger">שגיאה בשמירה: '+esc((err && (err.message||err.code)) || String(err))+'</p>';
      console.error('wmHandleEntrySaveErrorV516', err);
    }catch(e){}
    wmReleaseEntrySaveV525();
  }

  // v5.26:
  // פונקציות V516 נחשפות ל-window כי התקנות סיב/RF נשמרות מסקריפט V411 נפרד.
  window.wmBeginEntrySaveV516 = wmBeginEntrySaveV516;
  window.wmOfflineSaveNoticeV516 = wmOfflineSaveNoticeV516;
  window.wmAfterLocalEntrySaveV516 = wmAfterLocalEntrySaveV516;
  window.wmHandleEntrySaveErrorV516 = wmHandleEntrySaveErrorV516;

  async function addServiceWithStatusV49(status){
    const customerNumber=val('sCustomer'), address=val('sAddress'), notes=val('sNotes'), isReturnCall=$('sReturnCall')&&$('sReturnCall').checked;
    const amount=isReturnCall?0:SERVICE_PRICE;
    if(!customerNumber||!/^\d+$/.test(customerNumber))return $('entryMsg').innerHTML='<p class="danger">חובה למלא מספר לקוח בספרות בלבד.</p>';
    if(!address)return $('entryMsg').innerHTML='<p class="danger">חובה למלא כתובת.</p>';
    if(!wmBeginEntrySaveV516()) return;
    const label=status==='planned'?'קריאת השירות':'קריאת השירות';
    const successMsg=wmOfflineSaveNoticeV516(label, status==='planned'?null:amount, status, 'היא לא נכנסה להתחשבנות עד שתלחץ בוצע.');
    try{
      const writePromise=db.collection('workEntries').add({
        workerId:viewedWorker.id, workerName:viewedWorker.name, authUid:viewedWorker.authUid||currentAuthUid(),
        date:selectedDate, workType:'service', entryStatus:status,
        description:isReturnCall?'קריאת שירות חוזרת':'קריאת שירות', customerNumber,address,notes,isReturnCall,amount,
        createdAt:firebase.firestore.FieldValue.serverTimestamp()
      });
      // v5.16: לא עושים await כאן. באופליין ההבטחה עלולה להיסגר רק כשהשרת חוזר, אבל המשתמש צריך חיווי וניקוי מידיים.
      writePromise.then(function(){ try{ if(typeof loadMonth==='function') loadMonth(); }catch(e){} }).catch(wmHandleEntrySaveErrorV516);
      wmAfterLocalEntrySaveV516(successMsg);
    }catch(err){
      wmHandleEntrySaveErrorV516(err);
    }
  }

  async function addInstallWithStatusV49(status){
    const customerNumber=val('iCustomer'), address=val('iAddress'), notes=val('iNotes');
    if(!customerNumber||!/^\d+$/.test(customerNumber))return $('entryMsg').innerHTML='<p class="danger">חובה למלא מספר לקוח בספרות בלבד.</p>';
    if(!address)return $('entryMsg').innerHTML='<p class="danger">חובה למלא כתובת.</p>';
    let items=[], total=0;
    priceList.forEach(p=>{
      const el=$('qty_'+p.id); let q=0;
      if(el) q=(p.inputMode||'qty')==='check'?(el.checked?1:0):Number(el.value||0);
      if(q>0){
        items.push({id:p.id,name:p.name,price:Number(p.price||0),quantity:q,inputMode:p.inputMode||'qty',total:q*Number(p.price||0)});
        total+=q*Number(p.price||0);
      }
    });
    if(!items.length)return $('entryMsg').innerHTML='<p class="danger">חובה לבחור לפחות פריט אחד.</p>';
    if(!wmBeginEntrySaveV516()) return;
    const successMsg=wmOfflineSaveNoticeV516('ההתקנה', status==='planned'?null:total, status, 'היא לא נכנסה להתחשבנות עד שתלחץ בוצע.');
    try{
      const writePromise=db.collection('workEntries').add({
        workerId:viewedWorker.id, workerName:viewedWorker.name, authUid:viewedWorker.authUid||currentAuthUid(),
        date:selectedDate, workType:'install', entryStatus:status, description:'התקנה', customerNumber,address,notes,items,amount:total,
        createdAt:firebase.firestore.FieldValue.serverTimestamp()
      });
      // v5.16: לא עושים await כאן כדי שחיווי וניקוי שדות יעבדו גם כשהמכשיר אופליין.
      writePromise.then(function(){ try{ if(typeof loadMonth==='function') loadMonth(); }catch(e){} }).catch(wmHandleEntrySaveErrorV516);
      wmAfterLocalEntrySaveV516(successMsg);
    }catch(err){
      wmHandleEntrySaveErrorV516(err);
    }
  }

  window.addService=function(){ return addServiceWithStatusV49('done'); };
  window.addInstall=function(){ return addInstallWithStatusV49('done'); };
  window.addServicePlannedV49=function(){ return addServiceWithStatusV49('planned'); };
  window.addInstallPlannedV49=function(){ return addInstallWithStatusV49('planned'); };

  window.markEntryDoneV49=async function(id){
    if(!id)return;
    var e=(Array.isArray(monthEntries)?monthEntries:[]).find(function(x){return x.id===id;});
    var label=e ? workTypeNameV49(e)+(e.customerNumber?' ללקוח '+e.customerNumber:'') : 'העבודה';
    if(!confirm('לסמן את '+label+' כבוצע ולהכניס להתחשבנות?'))return;
    try{
      await db.collection('workEntries').doc(id).set({entryStatus:'done',doneAt:new Date().toISOString(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
      if($('entryMsg')) $('entryMsg').innerHTML='<div class="notice">העבודה סומנה כבוצעה ונכנסה להתחשבנות ✅</div>';
      await loadMonth();
    }catch(err){ alert('שגיאה בסימון בוצע: '+(err.code||err.message||err)); }
  };

  window.renderStats=function(){
    const worker=viewedWorker||{};
    const entries=Array.isArray(monthEntries)?monthEntries:[];
    const done=doneEntriesV49(entries);
    const planned=plannedEntriesV49(entries);
    const monthTotal=sumV49(done);
    const dayDone=selectedDate?done.filter(e=>e.date===selectedDate):[];
    const dayTotal=sumV49(dayDone);
    const plannedTotal=sumV49(planned);
    const dayPlannedTotal=selectedDate?sumV49(planned.filter(e=>e.date===selectedDate)):0;
    const goal=getWorkerGoalForMonthV556();
    const left=Math.max(goal-monthTotal,0);
    if($('monthTotal')) $('monthTotal').textContent=money(monthTotal);
    if($('dayTotal')) $('dayTotal').textContent=money(dayTotal);
    if($('goalTotal')) $('goalTotal').textContent=money(goal);
    if($('leftTotal')) $('leftTotal').textContent=money(left);
    if($('goalBar')) $('goalBar').style.width=goal?Math.min(monthTotal/goal*100,100)+'%':'0%';
    if($('paceLine')) $('paceLine').innerHTML=(goal?(left<=0?'מעולה — היעד הושג.':`חסר ליעד: ${money(left)}.`):'לא הוגדר יעד חודשי.')+`<br><span class="planned-badge-v49">📋 מתוכנן החודש: ${money(plannedTotal)} · ${planned.length} עבודות</span>`+(selectedDate&&dayPlannedTotal?` <span class="planned-badge-v49">ביום הנבחר: ${money(dayPlannedTotal)}</span>`:'');
  };

  window.renderCalendar=function(){
    const cal=$('calendar'); if(!cal)return; cal.innerHTML='';
    weekdays.forEach(w=>{const d=document.createElement('div');d.className='weekday';d.textContent=w;cal.appendChild(d)});
    const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0).getDate(),today=formatDate(new Date());
    for(let i=0;i<first.getDay();i++){const e=document.createElement('div');e.className='day empty';cal.appendChild(e)}
    for(let d=1;d<=last;d++){
      const ds=`${y}-${pad(m+1)}-${pad(d)}`,dt=new Date(y,m,d),sh=dt.getDay()===6;
      const all=(Array.isArray(monthEntries)?monthEntries:[]).filter(e=>e.date===ds);
      const done=doneEntriesV49(all), planned=plannedEntriesV49(all);
      const total=sumV49(done), plannedTotal=sumV49(planned);
      const div=document.createElement('div'); div.className='day';
      if(sh)div.classList.add('shabbat'); if(ds===today)div.classList.add('today'); if(ds===selectedDate)div.classList.add('selected');
      div.innerHTML=`<div class="day-num">${d}</div>${total?`<div class="day-total">${money(total)}</div>`:''}${done.length?`<div class="day-count">${done.length} בוצע</div>`:''}${planned.length?`<div class="day-planned-v49">📋 ${planned.length} מתוכנן<br>${money(plannedTotal)}</div>`:''}`;
      if(!sh)div.onclick=()=>selectDay(ds); cal.appendChild(div);
    }
  };

  window.renderDay=function(){
    ensurePlannedButtonsV49();
    if(!selectedDate){hide('dayPanel');show('selectDayHint');return}
    show('dayPanel');hide('selectDayHint');text('dateTitle',`יום ${heDate(selectedDate)}`);
    renderInstallItems();setType(selectedType,false);updateServicePriceLabels();ensurePlannedButtonsV49();
    const entries=(Array.isArray(monthEntries)?monthEntries:[]).filter(e=>e.date===selectedDate).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));
    const box=$('dayEntries');
    box.innerHTML=entries.length?'':'<p class="muted">אין עבודות ביום הזה עדיין.</p>';
    entries.forEach(e=>{
      const planned=isPlannedV49(e);
      const details=e.workType==='service'?`מספר לקוח: ${e.customerNumber||''}\nכתובת: ${e.address||''}\n${e.notes||''}`:`מספר לקוח: ${e.customerNumber||''}\nכתובת: ${e.address||''}\n`+(e.items||[]).map(i=>`${i.name} × ${i.quantity} = ${money(i.total)}`).join('<br>')+pekaLineV527(e)+`\n${e.notes||''}`;
      const row=document.createElement('div'); row.className='item'+(planned?' planned-card-v49':'');
      const iconClass=e.workType==='install'?'install':(e.isReturnCall?'return':'service');
      const icon=e.workType==='install'?'🛠️':(e.isReturnCall?'🔁':'☎️');
      row.innerHTML=`<div class="work-row-main"><div class="work-icon ${iconClass}">${planned?'📋':icon}</div><div><div class="item-title">${esc(e.description)} ${planned?'<span class="planned-badge-v49">מתוכנן</span>':'<span class="done-badge-v49">בוצע</span>'}</div><div class="item-sub">${nl2br(details)}</div></div></div><div><div class="money ${planned?'planned-money-v49':''}">${money(e.amount)}</div><div class="actions" style="margin-top:8px">${planned?`<button class="btn-green" onclick="markEntryDoneV49('${e.id}')">בוצע</button>`:''}<button class="btn-yellow" onclick="openEntryEdit('${e.id}')">ערוך</button>${(!planned&&e.workType==='install')?`<button class="btn-light" onclick="saveEntryAsTemplate('${e.id}')">שמור כתבנית</button>`:''}<button class="btn-red" onclick="deleteEntry('${e.id}')">מחק</button></div></div>`;
      box.appendChild(row);
    });
  };

  window.getFilteredEntries=function(){
    const customer=val('searchCustomer');
    const address=val('searchAddress').toLowerCase();
    const type=val('searchType');
    const date=val('searchDate');
    const month=val('searchMonth');
    const scope=(typeof getSearchDateScopeV507==='function') ? getSearchDateScopeV507() : {mode:'currentMonth'};
    const base=Array.isArray(window.searchBaseEntriesV507) ? window.searchBaseEntriesV507 : monthEntries;
    let arr=doneEntriesV49(base);
    if(customer) arr=arr.filter(e=>String(e.customerNumber||'').includes(customer));
    if(address) arr=arr.filter(e=>String(e.address||'').toLowerCase().includes(address));
    if(type) arr=arr.filter(e=>e.workType===type);
    if(!scope || scope.mode==='currentMonth'){
      if(date) arr=arr.filter(e=>e.date===date);
      if(month) arr=arr.filter(e=>String(e.date||'').startsWith(month));
    }
    return arr;
  };
  window.renderFullSummary=function(){ window.searchBaseEntriesV507=null; renderSummary(doneEntriesV49(monthEntries),'סיכום חודש בתצוגה - בוצע בלבד'); };

  window.renderSmartDashboard=function(){
    const box=$('smartDashboard'); if(!box)return;
    const entries=Array.isArray(monthEntries)?monthEntries:[];
    const done=doneEntriesV49(entries), planned=plannedEntriesV49(entries);
    const total=sumV49(done), plannedTotal=sumV49(planned);
    const workDays=[...new Set(done.map(e=>e.date))].length;
    const avg=workDays?total/workDays:0;
    const services=done.filter(e=>e.workType==='service');
    const installs=done.filter(e=>e.workType==='install');
    const plannedServices=planned.filter(e=>e.workType==='service');
    const plannedInstalls=planned.filter(e=>e.workType==='install');
    const goal=getWorkerGoalForMonthV556();
    const left=Math.max(goal-total,0);
    const progress=goal?Math.min(total/goal*100,100):0;
    box.innerHTML=`
      <div class="grid4">
        <div class="dash-card"><div class="dash-icon">💰</div><div class="dash-title">בוצע החודש</div><div class="dash-value">${money(total)}</div><div class="muted">נכנס להתחשבנות</div></div>
        <div class="dash-card planned-card-v49"><div class="dash-icon">📋</div><div class="dash-title">מתוכנן החודש</div><div class="dash-value planned-money-v49">${money(plannedTotal)}</div><div class="muted">לא נספר בהתחשבנות</div></div>
        <div class="dash-card"><div class="dash-icon">🎯</div><div class="dash-title">קצב ליעד</div><div class="dash-value">${Math.round(progress)}%</div><div class="muted">${left>0?'חסר '+money(left):'היעד הושג'}</div></div>
        <div class="dash-card"><div class="dash-icon">📊</div><div class="dash-title">ממוצע ליום בוצע</div><div class="dash-value">${money(avg)}</div><div class="muted">${workDays} ימי עבודה</div></div>
      </div>
      <div class="kpi-strip">
        <div class="kpi">קריאות בוצעו<b>${services.length}</b></div>
        <div class="kpi">התקנות בוצעו<b>${installs.length}</b></div>
        <div class="kpi planned-card-v49">קריאות מתוכננות<b>${plannedServices.length}</b></div>
        <div class="kpi planned-card-v49">התקנות מתוכננות<b>${plannedInstalls.length}</b></div>
      </div>
      <p><span class="planned-badge-v49">📋 כסף מתוכנן: ${money(plannedTotal)}</span> <span class="done-badge-v49">✅ כסף שבוצע: ${money(total)}</span></p>
    `;
  };

  const oldSetTypeV49=window.setType;
  window.setType=function(type,clear){
    const r=oldSetTypeV49?oldSetTypeV49(type,clear):undefined;
    setTimeout(ensurePlannedButtonsV49,0);
    return r;
  };

  document.addEventListener('DOMContentLoaded',function(){ setTimeout(ensurePlannedButtonsV49,300); });
  window.addEventListener('load',function(){ setTimeout(ensurePlannedButtonsV49,700); });
})();
